package com.aiinvestment.portfolio.api;
import com.aiinvestment.portfolio.application.Nifty500ReferenceService; import com.aiinvestment.portfolio.infrastructure.persistence.*; import com.aiinvestment.shared.web.auth.AuthenticatedUserResolver; import com.aiinvestment.portfolio.infrastructure.persistence.AppUserProvisioner; import jakarta.servlet.http.HttpServletRequest; import org.springframework.web.bind.annotation.*; import org.springframework.http.*; import org.springframework.data.domain.*; import java.util.*;
@RestController @RequestMapping("/api/v1/market-universe/india/nifty500") public class IndiaMarketUniverseController {final Nifty500ReferenceService refresh;final Nifty500UniverseRepository rows;final AppUserProvisioner users; public IndiaMarketUniverseController(Nifty500ReferenceService r,Nifty500UniverseRepository rows,AppUserProvisioner u){refresh=r;this.rows=rows;users=u;}
 @PostMapping("/refresh") public Nifty500ReferenceService.Counts refresh(HttpServletRequest q){users.upsert(AuthenticatedUserResolver.require(q));boolean admin=Arrays.stream(String.valueOf(q.getHeader("X-AIP-User-Roles")).split(",")).map(String::trim).anyMatch("ADMIN"::equalsIgnoreCase);if(!admin)throw new org.springframework.web.server.ResponseStatusException(HttpStatus.FORBIDDEN,"Admin role required");return refresh.refresh();}
 @GetMapping public Response list(@RequestParam(name="page",defaultValue="0")int page,@RequestParam(name="size",defaultValue="100")int size,HttpServletRequest q){users.upsert(AuthenticatedUserResolver.require(q));var p=rows.findAllByOrderBySymbolAscInstrumentIdAsc(PageRequest.of(Math.max(0,page),Math.min(500,Math.max(1,size))));return new Response(p.getContent().stream().map(Item::from).toList(),p.getNumber(),p.getSize(),p.getTotalElements());}
 public record Response(List<Item> instruments,int page,int size,long totalElements){} public record Item(UUID globalInstrumentId,String symbol,String companyName,String isin,String exchange,String mic,String country,String currency,String assetType,String status,String officialIndustry,String canonicalSector,String source,java.time.Instant retrievedAt){static Item from(Nifty500UniverseEntity x){return new Item(x.getInstrumentId(),x.getSymbol(),x.getCompanyName(),x.getIsin(),"NSE","XNSE","IN","INR","EQUITY","ACTIVE",x.getIndustry(),x.getCanonicalSector(),x.getSource(),x.getRetrievedAt());}}
}
